# Initially generated by GitHub Copilot.
"""Fix non-standard Hebrew mark order in .py and .json files."""

import re

from mb_cmn.uni_denorm import give_std_mark_order

import check_mark_order

WORD_RE = re.compile(r"[\u0590-\u05FF\u034F\uFB1E]+")
HAS_LETTER_RE = re.compile(r"[\u05D0-\u05EA]")


def fix_line(line):
    parts = []
    last_end = 0
    for m in WORD_RE.finditer(line):
        word = m.group()
        parts.append(line[last_end : m.start()])
        if HAS_LETTER_RE.search(word):
            parts.append(give_std_mark_order(word))
        else:
            parts.append(word)
        last_end = m.end()
    parts.append(line[last_end:])
    return "".join(parts)


# Scoped to book-of-job's own code and corpus, not to whatever repo holds them.  This walked up
# to .git and rewrote everything under the root it found, which was right while the
# code was book-of-job's whole tree and is not right now that the code sits inside
# MAM-basics: this script has no dry-run and writes on sight, so a repo-wide root
# here would reformat files nobody asked about.  See boj_paths' module docstring.
for p in sorted(check_mark_order._scoped_files()):
    text = p.read_text(encoding="utf-8")
    lines = text.split("\n")
    new_lines = [fix_line(line) for line in lines]
    new_text = "\n".join(new_lines)
    if new_text != text:
        p.write_text(new_text, encoding="utf-8", newline="")
        print(f"Fixed: {check_mark_order._display_path(p)}")
    else:
        pass  # no changes
